import { useState } from 'react';

export function MegaMenu() {
  const [open, setOpen] = useState(false);
  const cats = {{categories}};
  return (
    <div className="relative" onMouseLeave={() => setOpen(false)}>
      <button onMouseEnter={() => setOpen(true)} className="px-4 py-3 font-medium">Products ▾</button>
      {open && (
        <div className="absolute left-0 top-full z-20 w-screen max-w-4xl bg-white border shadow-xl p-8">
          <div className="grid grid-cols-4 gap-8">
            {cats.map((cat) => (
              <div key={cat.title}>
                <h4 className="mb-3 font-semibold text-gray-900">{cat.title}</h4>
                <ul className="space-y-2">
                  {cat.items.map((it) => (
                    <li key={it.href}><a href={it.href} className="text-sm text-gray-600 hover:text-blue-600">{it.label}</a></li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
